alter table public.complaints add constraint complaint_photo_owner check(photo='' or split_part(photo,'/',1)=owner::text);
alter table public.items add constraint item_photo_owner check(photo='' or split_part(photo,'/',1)=owner::text);
alter table public.profiles add constraint avatar_photo_owner check(avatar='' or split_part(avatar,'/',1)=id::text);
create function public.campus_publish_notice() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_table_name='events' then insert into public.notifications(user_id,kind,title,body) select p.id,'event','New campus event',new.title from public.profiles p where p.id<>new.owner and coalesce(p.preferences->>'event','true')='true'; elsif new.urgent then insert into public.notifications(user_id,kind,title,body) select p.id,'announcement','Important campus announcement',new.title from public.profiles p where p.id<>new.owner and coalesce(p.preferences->>'announcement','true')='true'; end if; return new; end $$;
revoke all on function public.campus_publish_notice() from public; create trigger campus_event_notice after insert on public.events for each row execute function public.campus_publish_notice(); create trigger campus_announcement_notice after insert on public.announcements for each row execute function public.campus_publish_notice();
create function public.campus_registration_notice() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.kind='registered' then insert into public.notifications(user_id,kind,title,body) select new.user_id,'deadline','Registration confirmed: '||e.title,'Event: '||to_char(e.starts_at at time zone 'UTC','Mon DD, YYYY HH24:MI')||' UTC · '||e.venue from public.events e where e.id=new.event_id and coalesce((select preferences->>'deadline' from public.profiles where id=new.user_id),'true')='true'; end if; return new; end $$;
revoke all on function public.campus_registration_notice() from public; create trigger campus_registration_notice after insert on public.event_activity for each row execute function public.campus_registration_notice();
create or replace function public.campus_insights() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin if not public.campus_role('admin') then raise exception 'Not authorized'; end if; return jsonb_build_object('events',(select count(*) from public.events),'registrations',(select count(*) from public.event_activity where kind='registered'),'complaints',(select count(*) from public.complaints),'resolved',(select count(*) from public.complaints where status='Resolved'),'categories',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from (select category as name,count(*) as total from public.complaints group by category order by count(*) desc) x),'event_counts',(select coalesce(jsonb_agg(to_jsonb(z)),'[]') from (select e.title as name,count(a.event_id) as total from public.events e left join public.event_activity a on a.event_id=e.id and a.kind='registered' group by e.id order by count(a.event_id) desc limit 20) z),'engagement',(select coalesce(jsonb_agg(to_jsonb(w)),'[]') from (select to_char(date_trunc('week',created_at),'Mon DD') as name,count(*) as total from public.event_activity where kind='registered' group by date_trunc('week',created_at) order by date_trunc('week',created_at) desc limit 8) w),'interests',(select coalesce(jsonb_agg(to_jsonb(s)),'[]') from (select left(lower(btrim(word)),80) as name,count(distinct p.id) as total from public.profiles p cross join lateral regexp_split_to_table(p.interests,',') word where btrim(word)<>'' group by 1 having count(distinct p.id)>=3 order by 2 desc limit 8) s),'careers',(select coalesce(jsonb_agg(to_jsonb(c)),'[]') from (select left(lower(btrim(goals)),80) as name,count(*) as total from public.profiles where btrim(goals)<>'' group by 1 having count(*)>=3 order by 2 desc limit 8) c)); end $$;